      "kind": "structured-document",
      "native": {
        "id": null,
        "value": {
          "jobs": {
            "sync": {
              "permissions": {
                "contents": "write"
              },
              "runs-on": "ubuntu-latest",
              "steps": [
                {
                  "name": "Checkout interdependent-lib",
                  "uses": "actions/checkout@v7.0.1"
                },
                {
                  "name": "Sync pcea lib",
                  "run": "rm -rf /tmp/pcea-src\ngit clone --depth 1 https://github.com/The-Interdependency/PCEA.git /tmp/pcea-src\nmkdir -p libs/pcea/src\nrsync -av --delete --exclude='README.md' /tmp/pcea-src/pcea/ libs/pcea/src/\n"
                },
                {
                  "name": "Sync ptcna package",
                  "run": "rm -rf /tmp/ptcna-src\ngit clone --depth 1 https://github.com/The-Interdependency/ptcna.git /tmp/ptcna-src\nmkdir -p libs/ptcna/src\nrsync -av --delete --exclude='README.md' /tmp/ptcna-src/ptcna/ libs/ptcna/src/\n"
                },
                {
                  "name": "Sync ucns lib",
                  "run": "rm -rf /tmp/ucns-src\ngit clone --depth 1 https://github.com/The-Interdependency/ucns.git /tmp/ucns-src\nmkdir -p libs/ucns/src\nrsync -av --delete --exclude='README.md' /tmp/ucns-src/ucns/ libs/ucns/src/\n"
                },
                {
                  "name": "Sync aimmh lib",
                  "run": "rm -rf /tmp/aimmh-src\ngit clone --depth 1 https://github.com/The-Interdependency/aimmh.git /tmp/aimmh-src\nmkdir -p libs/aimmh/src\nrsync -av --delete --exclude='README.md' /tmp/aimmh-src/aimmh_lib/ libs/aimmh/src/\n"
                },
                {
                  "name": "Commit synced files",
                  "run": "git config user.name  \"github-actions[bot]\"\ngit config user.email \"github-actions[bot]@users.noreply.github.com\"\ngit add libs/\nif git diff --cached --quiet; then\n  echo \"No changes to commit.\"\nelse\n  git commit -m \"chore: sync lib sources from upstream repos [skip ci]\"\n  git push\nfi\n"
                }
              ]
            }
          },
          "name": "Sync lib folders from source repos",
          "on": {
            "schedule": [
              {
                "cron": "0 3 * * 1"
              }
            ],
            "workflow_dispatch": null
          }
        }
      },
